class Solution {
public:
    vector<int> kthSmallest(vector<int>& par, vector<int>& vals, vector<vector<int>>& queries) {
        int n=vals.size();
        vector<vector<int>> children(n);
        for(int i=1;i<n;++i) children[par[i]].push_back(i);
        vector<int> tin(n),tout(n),order(n),xr(n),iter(n,0);
        vector<int> stack(1,0);
        xr[0]=vals[0]; int timer=0;
        while(!stack.empty()) {
            int u=stack.back();
            if(iter[u]==0) {tin[u]=timer;order[timer++]=xr[u];}
            if(iter[u]<(int)children[u].size()) {
                int v=children[u][iter[u]++];
                xr[v]=xr[u]^vals[v]; stack.push_back(v);
            } else {tout[u]=timer-1;stack.pop_back();}
        }
        vector<int> sorted=order;
        sort(sorted.begin(),sorted.end());
        sorted.erase(unique(sorted.begin(),sorted.end()),sorted.end());
        for(int &v:order) v=lower_bound(sorted.begin(),sorted.end(),v)-sorted.begin();
        struct Q {int l,r,k,id;};
        vector<Q> qs;
        for(int i=0;i<(int)queries.size();++i)
            qs.push_back({tin[queries[i][0]],tout[queries[i][0]],queries[i][1],i});
        int block=max(1,(int)sqrt(n));
        sort(qs.begin(),qs.end(),[&](const Q&a,const Q&b) {
            if(a.l/block!=b.l/block) return a.l/block<b.l/block;
            return (a.l/block&1)?a.r>b.r:a.r<b.r;
        });
        int m=sorted.size();
        vector<int> bit(m+1,0),freq(m,0),ans(qs.size(),-1);
        auto update=[&](int p,int delta) {
            int old=freq[p];freq[p]+=delta;
            int change=(freq[p]>0)-(old>0);
            for(int i=p+1;i<=m;i+=i&-i) bit[i]+=change;
        };
        auto kth=[&](int k) {
            int idx=0,step=1;
            while(step*2<=m) step*=2;
            for(;step;step/=2) if(idx+step<=m && bit[idx+step]<k) {
                k-=bit[idx+step];idx+=step;
            }
            return sorted[idx];
        };
        int L=0,R=-1,distinct=0;
        for(auto &q:qs) {
            while(L>q.l) update(order[--L],1);
            while(R<q.r) update(order[++R],1);
            while(L<q.l) update(order[L++],-1);
            while(R>q.r) update(order[R--],-1);
            int total=0;
            for(int i=m;i>0;i-=i&-i) total+=bit[i];
            if(q.k<=total) ans[q.id]=kth(q.k);
        }
        return ans;
    }
};
